      empty.className = "hempty";
      empty.style.minHeight = "58vh";
      empty.innerHTML = '<svg viewBox="0 0 24 24"><path d="M20 2H4c1.1 02 .92 2v18l44h14c1.1 0 2.9 22V4c01.1.9222z"></path></svg><p>Kezdj új beszélgetést a Bytez és Claude Opus 4.6 modellel.</p>';
      ml.appendChild(empty);
      updateChip();
      goBottom(false);
      return;
    }
    for (const message of session.messages) {
      if (message.role === "user") ml.appendChild(makeUserMessage(message));
      else if (message.role === "assistant") ml.appendChild(makeAssistantMessage(message));
    }
    updateChip();
    goBottom(false);
  }

  function renderHistory() {
    sortSessions();
    const query = searchInput.value.trim().toLowerCase();
    const visible = sessions.filter(session => !query || session.title.toLowerCase().includes(query) || session.messages.some(message => String(message.content || "").toLowerCase().includes(query)));
    hlist.innerHTML = "";
    if (!visible.length) {
      const empty = document.createElement("div");
      empty.className = "hempty";
      empty.innerHTML = '<svg viewBox="0 0 24 24"><path d="M20 2H4c1.1 02 .92 2v18l44h14c1.1 0 2.9 22V4c01.1.9222z"></path></svg><p>' + (query ? "Nincs találat" : "Még nincs beszélgetés") + '</p>';
      hlist.appendChild(empty);
      return;
    }
    for (const session of visible) {
      const card = document.createElement("div");
      card.className = "hcard" + (session.id === currentSessionId ? " active" : "");
      const body = document.createElement("div");
      body.className = "hcardbody";
      const pre = document.createElement("div");
      pre.className = "hcardpre";
      pre.textContent = session.title || "Új beszélgetés";
      const meta = document.createElement("div");
      meta.className = "hcardmeta";
      meta.textContent = new Date(session.updatedAt).toLocaleString([], { month: "short", day: "numeric", hour: "2digit", minute: "2digit" });
      body.appendChild(pre);
