  function toast(message, type, ms) {
    const icons = {
      err: '<svg viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 104.48 1010S17.52 2 12 2zm1 15h2v2h2v2zm04h2V7h2v6z"></path></svg>',
      ok: '<svg viewBox="0 0 24 24"><path d="M9 16.17 4.83 12l1.42 1.41L9 19 21 7l1.411.41z"></path></svg>',
      inf: '<svg viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 104.48 1010S17.52 2 12 2zm1 15h2v6h2v6zm08h2V7h2v2z"></path></svg>'
    };
    const el = document.createElement("div");
    el.className = "toast " + type;
    el.innerHTML = (icons[type] || icons.inf) + "<span>" + escapeHtml(message) + "</span>";
    $("toasts").appendChild(el);
    const dismiss = () => {
      el.classList.add("out");
      setTimeout(() => el.remove(), 220);
    };
    el.addEventListener("click", dismiss);
    setTimeout(dismiss, ms || 3000);
  }

  function nearBottom(distance) {
