  }

  function updateScrollButton() {
    stb.classList.toggle("show", !nearBottom(200));
  }

  function autosize() {
    ta.style.height = "auto";
    ta.style.height = Math.min(ta.scrollHeight, 104) + "px";
    sbtn.disabled = !ta.value.trim() || sending;
  }

  function normalizeAssistantText(value) {
    if (typeof value === "string") return value;
    if (Array.isArray(value)) {
      return value.map(normalizeAssistantText).filter(Boolean).join("\n\n");
    }
    if (value && typeof value === "object") {
      if (Array.isArray(value.choices) && value.choices.length) {
        const parts = value.choices.map(choice => {
          if (choice && choice.message && typeof choice.message.content === "string") return choice.message.content;
          if (choice && typeof choice.text === "string") return choice.text;
          return normalizeAssistantText(choice);
        }).filter(Boolean);
        if (parts.length) return parts.join("\n\n");
      }
      if (Array.isArray(value.content)) {
        const parts = value.content.map(item => {
          if (typeof item === "string") return item;
          if (item && typeof item === "object") {
            if (typeof item.text === "string") return item.text;
            if (typeof item.content === "string") return item.content;
          }
          return "";
        }).filter(Boolean);
        if (parts.length) return parts.join("\n\n");
      }
      if (typeof value.text === "string") return value.text;
      if (typeof value.content === "string") return value.content;
      if (typeof value.output_text === "string") return value.output_text;
      return JSON.stringify(value, null, 2);
    }
    if (value == null) return "";
    return String(value);
  }

  async function sendMessage() {
